import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import java.util.UUID;

@Component
public class OrderCreationHelper {

    @Autowired
    private OrderRepository orderRepository;

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public Order findOrCreate(UUID orderId, UUID customerId, UUID productId, int quantity) {
        return orderRepository.findById(orderId).orElseGet(() -> {
            try {
                return orderRepository.saveAndFlush(new Order(orderId, customerId, productId, quantity));
            } catch (DataIntegrityViolationException e) {
                return orderRepository.findById(orderId).orElseThrow();
            }
        });
    }
}

